import json

# Parse each result
all_classifications = {}
for chunk_idx, (chunk, result) in enumerate(zip(chunks, results)):
    try:
        parsed = json.loads(result)
        print(f"Chunk {chunk_idx}: parsed {len(parsed)} items")
        # Map global index
        for local_idx, category in parsed.items():
            global_idx = chunk_idx * CHUNK + int(local_idx)
            all_classifications[global_idx] = category
    except json.JSONDecodeError as e:
        print(f"Chunk {chunk_idx} parse error: {e}")
        print(f"Raw result: {result}")

print(f"\nTotal classified: {len(all_classifications)}")
print(f"Expected: {len(questions)}")

# Check coverage
if len(all_classifications) < len(questions):
    print("MISSING classifications!")
    missing = [i for i in range(len(questions)) if i not in all_classifications]
    print(f"Missing indices: {missing}")
    for idx in missing:
        print(f"  {idx}: {questions[idx]}")

